import {describe,it,expect} from 'vitest';
import {measureArea,classifyCandidate,compareShadow,worldPoint,type Feature} from '../supabase/functions/_shared/areaShadow';
import {areaWindow} from '../supabase/functions/_shared/rainArea';
import {classifyRainPixel} from '../lib/weather/providers/jma/classifyPixel';
import {makeSnapshot,jmaTime,type Evidence} from '../supabase/functions/_shared/rainReplay';
const location={latitude:35.66,longitude:139.82},w=areaWindow(location.latitude,location.longitude);
function image(color=[0,0,0,0]){const rgba=new Uint8Array(w.width*w.height*4);for(let i=0;i<rgba.length;i+=4)rgba.set(color,i);return {rgba,mask:new Uint8Array(w.width*w.height).fill(1)};}
const center=(w.centerY-w.originY)*w.width+w.centerX-w.originX;
const metrics=(color=[0,0,0,0])=>{const i=image(color);return measureArea(i.rgba,i.mask,w,location,classifyRainPixel);};
const rain=()=>metrics([160,210,255,255]);
function fixture(){
 const base='20261029020000',target=Date.parse('2026-10-29T02:10:00Z');
 const forecast=[0,5,10].map(d=>({baseTime:base,validTime:jmaTime(target+d*60000),status:'NO_RAIN',rgba:{r:0,g:0,b:0,a:0}}));
 const s=makeSnapshot({eventType:'ACTIONABLE_RAIN_APPROACHING',decidedAt:'2026-10-29T02:01:00Z',latitude:location.latitude,longitude:location.longitude,title:'',body:'',rain:{event:{actionableAt:jmaTime(target)},forecast,observation:[{baseTime:'20261029020000',validTime:'20261029020000',status:'NO_RAIN'}]},previousState:null})!;
 const features:Feature[]=forecast.map(f=>({kind:'FORECAST',baseTime:base,validTime:f.validTime,pngSha256:'hash',matchesInputPixel:true,capturedAt:'2026-10-29T02:02:00Z',metrics:rain()}));
 const obs:Evidence[]=forecast.map(f=>({kind:'OBSERVATION',baseTime:f.validTime,validTime:f.validTime,status:'RAIN',capturedAt:'2026-10-29T02:30:00Z'}));
 return {s,features,obs,now:Date.parse('2026-10-29T03:00:00Z')};
}
describe('area shadow metrics',()=>{
 it('measures three circles with physical area and independent intensity bins',()=>{const m=rain();for(const r of [250,500,1000]){const c=m.circles[String(r)];expect(c.rainFraction).toBe(1);expect(c.usableCoverage).toBe(1);expect(c.intensityFractions['1_TO_5']).toBe(1);expect(c.intensityFractions.LT_1).toBe(0);expect(Math.abs(c.sampledAreaM2/(Math.PI*r*r)-1)).toBeLessThan(0.04);}expect(m.occupancyIsProbability).toBe(false);});
 it('keeps unknown and missing out of the dry denominator',()=>{const i=image([1,2,3,255]);const m=measureArea(i.rgba,i.mask,w,location,classifyRainPixel);expect(m.circles['500'].rainFraction).toBeNull();expect(m.circles['500'].unknownFraction).toBe(1);i.mask.fill(0);const missing=measureArea(i.rgba,i.mask,w,location,classifyRainPixel);expect(missing.circles['500'].missingFraction).toBe(1);expect(missing.circles['500'].rainFraction).toBeNull();});
 it('does not treat missing corners outside the circle as in-circle missing',()=>{const i=image();i.mask[0]=0;const m=measureArea(i.rgba,i.mask,w,location,classifyRainPixel);expect(m.circles['500'].usableCoverage).toBe(1);expect(m.circles['1000'].usableCoverage).toBe(1);});
 it('detects an enclosed dry hole but never fills its pixels',()=>{const i=image([160,210,255,255]);i.rgba.set([0,0,0,0],center*4);const m=measureArea(i.rgba,i.mask,w,location,classifyRainPixel);expect(m.center.status).toBe('NO_RAIN');expect(m.circles['500'].centerDryHoleM2).toBeGreaterThan(0);expect(m.circles['500'].rainFraction).toBeLessThan(1);expect(m.circles['500'].rainComponentCount).toBe(1);});
 it('does not declare a hole surrounded by missing data',()=>{const i=image([160,210,255,255]);i.rgba.set([0,0,0,0],center*4);i.mask[center+1]=0;expect(measureArea(i.rgba,i.mask,w,location,classifyRainPixel).circles['500'].centerDryHoleM2).toBeNull();});
 it('rejects bad geometry, cropped circles and invalid masks',()=>{const i=image();expect(()=>measureArea(i.rgba,i.mask,{...w,metersPerPixel:1},location,classifyRainPixel)).toThrow('GEOMETRY');expect(()=>measureArea(i.rgba,i.mask,{...w,originX:w.centerX},location,classifyRainPixel)).toThrow('CROP_TOO_SMALL');i.mask[0]=2;expect(()=>measureArea(i.rgba,i.mask,w,location,classifyRainPixel)).toThrow('SHAPE');});
 it('uses true subpixel coordinates rather than assuming the target is a pixel center',()=>{const p=worldPoint(location.latitude,location.longitude);expect(p.x-Math.floor(p.x)).not.toBe(0.5);expect(p.y-Math.floor(p.y)).not.toBe(0.5);expect(metrics().circles['250'].rainFraction).toBe(0);});
 it('compares 20/40/60 percent thresholds without presenting them as calibrated',()=>{const m=rain();m.circles['500'].rainFraction=0.3;m.circles['250'].rainFraction=0.3;expect(classifyCandidate('NO_RAIN',m,0.2,'INDETERMINATE','area')).toBe('RAIN');expect(classifyCandidate('NO_RAIN',m,0.4,'INDETERMINATE','area')).toBe('INDETERMINATE');expect(classifyCandidate('NO_RAIN',m,0.6,'INDETERMINATE','area')).toBe('NO_RAIN');});
 it('keeps a gray-band prior state, releases at half threshold, and gates poor coverage',()=>{const m=rain();m.circles['500'].rainFraction=0.3;expect(classifyCandidate('NO_RAIN',m,0.4,'RAIN','area')).toBe('RAIN');m.circles['500'].rainFraction=0.1;expect(classifyCandidate('NO_RAIN',m,0.4,'RAIN','area')).toBe('NO_RAIN');m.circles['250'].usableCoverage=0.8;expect(classifyCandidate('RAIN',m,0.4,'RAIN','combined')).toBe('INDETERMINATE');});
 it('does not infer local rain from distant rain alone in the combined candidate',()=>{const m=rain();m.circles['250'].rainFraction=0;expect(classifyCandidate('NO_RAIN',m,0.4,'INDETERMINATE','combined')).toBe('INDETERMINATE');expect(classifyCandidate('NO_RAIN',m,0.4,'INDETERMINATE','area')).toBe('RAIN');});
 it('scores all methods against the same recorded radar-center truth',()=>{const f=fixture(),r=compareShadow(f.s,f.features,f.obs,{exact:'MISMATCH'},f.now);expect(r.groups[0].point.scores[0].verdict).toBe('MISMATCH');expect(r.groups[0].variants[0].area.scores[0].verdict).toBe('MATCH');expect(r.truth).toBe('RECORDED_RADAR_CENTER_NOT_GROUND_RAIN');expect(r.currentProduction.radarResult).toEqual({exact:'MISMATCH'});});
 it('rejects input-mismatched, late-retrieved and coarse-horizon images as prospective features',()=>{for(const mutate of [(f:Feature)=>f.matchesInputPixel=false,(f:Feature)=>f.capturedAt='2026-10-29T02:40:00Z']){const f=fixture();f.features.forEach(mutate);expect(compareShadow(f.s,f.features,f.obs,null,f.now).groups[0].variants[0].area.series[0].state).toBe('INDETERMINATE');}const f=fixture();f.s.forecast[0].validTime='20261029023500';f.features[0].validTime='20261029023500';expect(compareShadow(f.s,f.features,f.obs,null,f.now).groups[0].variants[0].area.series.at(-1)?.state).toBe('INDETERMINATE');});
 it('never scores a forecast frame or future data as observed truth',()=>{const f=fixture();f.obs[0].baseTime='20261029020000';expect(compareShadow(f.s,f.features,f.obs,null,f.now).groups[0].point.scores[0].verdict).toBe('INDETERMINATE');expect(compareShadow(f.s,f.features,f.obs,null,0).groups[0].point.scores[0].verdict).toBe('INDETERMINATE');});
 it('does not claim consecutive confirmation across a missing five-minute frame',()=>{const f=fixture();f.s.forecast[1].validTime='20261029022500';expect(compareShadow(f.s,f.features,f.obs,null,f.now).groups[0].point.transitions.rainStartsAt).toBeNull();});
});

it('rejects duplicate original forecast frames rather than inflating the comparison sample',()=>{const f=fixture();f.s.forecast.push({...f.s.forecast[0]});expect(()=>compareShadow(f.s,f.features,f.obs,null,f.now)).toThrow('DUPLICATE_FORECAST');});
it('rejects a capture timestamp beyond the analysis clock',()=>{const f=fixture();f.features[0].capturedAt='2026-10-29T04:00:00Z';expect(compareShadow(f.s,f.features,f.obs,null,f.now).groups[0].variants[0].area.series[0].reason).toBe('INVALID_CAPTURE_TIME');});

it('excludes already-valid input frames from prospective agreement counts',()=>{const f=fixture();f.s.forecast.unshift({baseTime:'20261029020000',validTime:'20261029020000',status:'NO_RAIN'});const result=compareShadow(f.s,f.features,f.obs,null,f.now);expect(result.groups[0].point.scores).toHaveLength(3);expect(result.groups[0].point.scores.every(s=>s.leadMinutes>0)).toBe(true);});
